solution.javascript:
function fusionar(a, b) {
  const dummy = new ListNode(0);
  let cola = dummy;
  while (a && b) {
    if (a.val <= b.val) { cola.next = a; a = a.next; }
    else { cola.next = b; b = b.next; }
    cola = cola.next;
  }
  cola.next = a ?? b;
  return dummy.next;
}

solution.python:
def fusionar(a, b):
    dummy = cola = ListNode(0)
    while a and b:
        if a.val <= b.val:
            cola.next, a = a, a.next
        else:
            cola.next, b = b, b.next
        cola = cola.next
    cola.next = a or b
    return dummy.next
